import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { SheetBody } from '../../slots/defs/sheet';
import { usePeople } from '../people/people';
import { cutThen, poolsKey, usePeriodCuts, usePools } from './pools';
import type { Pool, PoolMember } from './pools';

/** A share as typed: a percent of at most two decimals, more than 0.00 and at most 100.00. */
function validShare(share: string): boolean {
  if (!/^\d+(\.\d{1,2})?$/.test(share)) return false;
  const n = Number(share);
  return n > 0 && n <= 100;
}

/** A member's key on screen: the person's id, or pool-<name> for a member pool. */
function memberKey(m: PoolMember): string {
  return m.poolId !== null ? `pool-${m.name}` : String(m.personId);
}

/** One pool: its total share, whether balanced, each member's share, and the entry a member (a person, or another
 *  pool chosen as pool:<name>) is added with — none for a crew's pool, whose members are the crew's. */
function PoolRow({ sheetId, user, pool, pools, periodCuts }: { sheetId: string; user: string; pool: Pool; pools: Pool[];
    periodCuts: { period: string; pools: Pool[] }[] }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId).data ?? [];
  // the chosen member: a person's id, or pool:<id>
  const [personId, setPersonId] = useState('');
  const [share, setShare] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  /** Refuse the add: show why, and drop the dates typed for it (a refused membership's dates are not kept). */
  const refuse = (message: string) => {
    setError(message);
    setFrom('');
    setTo('');
  };

  const add = useMutation({
    mutationFn: (body: { personId?: number; memberPoolId?: number; share: string; from?: string; to?: string }) =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/pools/${pool.id}/members`, { user, ...body }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
      setPersonId('');
      setShare('');
      setFrom('');
      setTo('');
    },
    onError: (e) => refuse(e instanceof HttpError && e.body ? e.body : 'Could not add the pool member.'),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (personId === '') {
      refuse('Choose the person or pool to add.');
      return;
    }
    const s = share.trim();
    if (!validShare(s)) {
      refuse('A share is more than 0.00 and at most 100.00, with at most two decimals.');
      return;
    }
    if (from !== '' && to !== '' && to < from) {
      refuse('The to-date cannot be before the from-date.');
      return;
    }
    const memberPoolId = personId.startsWith('pool:') ? Number(personId.slice(5)) : null;
    if (memberPoolId === null && pool.members.some((m) => m.poolId === null && String(m.personId) === personId)) {
      refuse('That person is already in the pool.');
      return;
    }
    if (!once.start()) return;
    const dates = { ...(from !== '' && { from }), ...(to !== '' && { to }) };
    add.mutate(
      memberPoolId !== null ? { memberPoolId, share: s, ...dates } : { personId: Number(personId), share: s, ...dates },
    );
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total share <span data-testid="pool-total-share">{pool.totalShare}</span>,
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li key={memberKey(m)} data-testid={`pool-member-${pool.name}-${memberKey(m)}`}>
            {m.poolId !== null ? `pool ${m.name}` : m.name}: <span data-testid="pool-share">{m.share}</span>, cut <span data-testid="pool-cut">{m.cut}</span>
            {periodCuts.map((pc) => (
              <span key={pc.period}>
                , {pc.period} <span data-testid={`pool-cut-${pc.period}`}>{cutThen(pc.pools, pool.id, m)}</span>
              </span>
            ))}
            {(m.from || m.to) && ` (${m.from || '…'} to ${m.to || '…'})`}
            {m.retired && ' (retired)'}
            {m.outside && ' (not a member today)'}
          </li>
        ))}
      </ul>
      {pool.crewId === null && (
        <>
          <form onSubmit={submit}>
            <select
              data-testid="pool-member-select"
              value={personId}
              onChange={(e) => {
                setPersonId(e.target.value);
                setError('');
              }}
            >
              <option value="">Person or pool…</option>
              {people.map((p) => (
                <option key={p.id} value={String(p.id)}>
                  {p.name}
                </option>
              ))}
              {pools.filter((p) => p.crewId === null).map((p) => (
                <option key={`pool:${p.id}`} value={`pool:${p.id}`}>
                  {`pool:${p.name}`}
                </option>
              ))}
            </select>{' '}
            <input
              data-testid="pool-member-share"
              placeholder="Share %"
              value={share}
              onChange={(e) => {
                setShare(e.target.value);
                setError('');
              }}
            />{' '}
            <input
              type="date"
              data-testid="pool-member-from"
              aria-label="Member from"
              value={from}
              onChange={(e) => {
                setFrom(e.target.value);
                setError('');
              }}
            />{' '}
            <input
              type="date"
              data-testid="pool-member-to"
              aria-label="Member to"
              value={to}
              onChange={(e) => {
                setTo(e.target.value);
                setError('');
              }}
            />{' '}
            <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
              Add member
            </button>
          </form>
          {error && (
            <p data-testid="pool-error" role="alert">
              {error}
            </p>
          )}
        </>
      )}
    </li>
  );
}

function PoolForm({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const once = useSubmitOnce();

  const save = useMutation({
    mutationFn: (n: string) => postJson<Pool>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`, { user, name: n }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
      setName('');
    },
    onError: (e) => setError(e instanceof HttpError && e.body ? e.body : 'Could not add the pool.'),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (name.trim() === '') {
      setError('Give the pool a name.');
      return;
    }
    if (!once.start()) return;
    save.mutate(name.trim());
  };

  return (
    <form data-testid="pool-form" onSubmit={submit}>
      <input
        data-testid="pool-form-name"
        placeholder="Pool name"
        value={name}
        onChange={(e) => {
          setName(e.target.value);
          setError('');
        }}
      />{' '}
      <button type="submit" data-testid="pool-form-submit" disabled={save.isPending}>
        Add pool
      </button>
      {error && (
        <p data-testid="pool-form-error" role="alert">
          {error}
        </p>
      )}
    </form>
  );
}

/** The sheet's pools: each with its members and their shares, its total share (a member retired by the sheet's
 *  today counts their share as given) and whether it is balanced, and the entry a pool is added with. */
function Pools({ sheetId, user }: { sheetId: string; user: string }) {
  const pools = usePools(sheetId).data ?? [];
  const periodCuts = usePeriodCuts(sheetId);
  return (
    <section data-testid="pools">
      <h2>Pools</h2>
      <PoolForm sheetId={sheetId} user={user} />
      <ul>
        {pools.map((p) => (
          <PoolRow key={p.id} sheetId={sheetId} user={user} pool={p} pools={pools} periodCuts={periodCuts} />
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 7.8, Component: Pools });
import { useQueries, useQuery } from '@tanstack/react-query';
import { getJson, getJsonNow } from '../../api/http';
import { usePeriods } from '../periods/periods';
import { useSheetToday } from '../sheet/sheet';

/** A member of a pool — a person, or another pool (poolId; personId then null) — with their share percent, whether
 *  they are retired by the sheet's today (their share still counts toward the pool's total but they cut 0.00, their
 *  share spread over the others), and their cut of the pool's pot ('' when the pool is unbalanced, there is no pot
 *  or every member is retired). A pool that is a member of none has the sheet's
 *  pot; a member pool's pot is its cut in the pool above. A membership may carry a from- and a to-date ('' when
 *  open); a member whose dates leave out the sheet's today (outside) counts nothing toward the total and has no cut. */
export type PoolMember = {
  personId: number | null;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
  poolId: number | null;
  from: string;
  to: string;
  outside: boolean;
};

/** A pool on the sheet: its members in the order they were added, the total of their shares and whether it is
 *  balanced (the total is exactly 100.00). A crew is also listed as a pool, after the pools: crewId is its crew's id
 *  (null for a pool), its members the lead and the crew's members at equal shares. */
export type Pool = {
  id: number;
  name: string;
  members: PoolMember[];
  totalShare: string;
  balanced: boolean;
  crewId: number | null;
};

export const poolsKey = (sheetId: string) => ['sheet', sheetId, 'pools'] as const;

/** The sheet's pools, in the order they were added. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`),
  });
}

/** The cuts at the end of each period whose to-date is on or before the sheet's today: by period name, the sheet's
 *  pools as they stood at the end of its to-date (that day as the sheet's today). Keyed under the sheet, so a load
 *  of the sheet re-reads them. */
export function usePeriodCuts(sheetId: string): { period: string; pools: Pool[] }[] {
  const today = useSheetToday(sheetId);
  const periods = (usePeriods(sheetId).data ?? []).filter((p) => today !== '' && p.to <= today);
  const results = useQueries({
    queries: periods.map((p) => ({
      queryKey: [...poolsKey(sheetId), 'asOf', p.to] as const,
      queryFn: () => getJsonNow<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools?asOf=${encodeURIComponent(p.to)}`),
    })),
  });
  return periods.map((p, i) => ({ period: p.name, pools: results[i]?.data ?? [] }));
}

/** A member's cut in a pool as it stood in an earlier read of the pools ('' when there was none). */
export function cutThen(pools: Pool[], poolId: number, member: PoolMember): string {
  const pool = pools.find((p) => p.id === poolId);
  const m = pool?.members.find((x) => x.poolId !== null ? x.poolId === member.poolId : x.personId === member.personId);
  return m?.cut ?? '';
}

function cents(amount: string): number {
  return Math.round(Number(amount) * 100);
}

function formatCents(total: number): string {
  const abs = Math.abs(total);
  return `${total < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}

/** A person's cuts, in cents, across every pool they are a member of (a pool showing no cut adds nothing). */
function personCutCents(pools: Pool[], personId: number): number {
  return pools
    .flatMap((p) => p.members)
    .filter((m) => m.poolId === null && m.personId === personId && m.cut !== '')
    .reduce((total, m) => total + cents(m.cut), 0);
}

/** A person's cut total: their cuts across every pool they are a member of, added up. */
export function personCutTotal(pools: Pool[], personId: number): string {
  return formatCents(personCutCents(pools, personId));
}

/** The sheet's cut total: every listed person's cut total added up. */
export function sheetCutTotal(pools: Pool[], personIds: number[]): string {
  return formatCents(personIds.reduce((total, id) => total + personCutCents(pools, id), 0));
}

